_BOT_NOT_FOUND_MESSAGE = "Bot not found"

# A simple in-memory store for training sessions and running bots
trainings: Dict[str, TrainingSession] = {}
running_bots: Dict[str, BotSession] = {}


def prepare_working_directories() -> None:
    """Make sure all required directories exist."""
    os.makedirs(logs_base_path(), exist_ok=True)
    os.makedirs(models_base_path(), exist_ok=True)


def cleanup_training_processes() -> None:
    """Terminate all running training processes."""
    structlogger.debug("model_trainer.cleanup_processes.started")
    running = list(trainings.values())
    for training in running:
        terminate_training(training)


def cleanup_bot_processes() -> None:
    """Terminate all running bot processes."""
    structlogger.debug("model_runner.cleanup_processes.started")
    running = list(running_bots.values())
    for bot in running:
        terminate_bot(bot)


def _auto_deploy_bot(training: TrainingSession) -> None:
    """Start a bot for a training session that completed with deploy=True."""
    deployment_id = training.training_id
    existing_bot = running_bots.get(deployment_id)
    if existing_bot is not None:
        if existing_bot.status != BotSessionStatus.STOPPED:
            structlogger.warning(
                "model_api.auto_deploy.skipped_already_exists",
                deployment_id=deployment_id,
            )
            return
        del running_bots[deployment_id]
        structlogger.info(
            "model_api.auto_deploy.redeploying_stopped_bot",
            deployment_id=deployment_id,
        )

    active_count = sum(
        1
        for bot in running_bots.values()
        if bot.status in {BotSessionStatus.RUNNING, BotSessionStatus.QUEUED}
    )
    if active_count >= int(config.MAX_PARALLEL_BOT_RUNS):
        try:
            evict_oldest_inactive_bot(running_bots)
        except AllBotsRecentlyActiveError:
            structlogger.warning(
                "model_api.auto_deploy.skipped_capacity",
                deployment_id=deployment_id,
                max_parallel_bot_runs=config.MAX_PARALLEL_BOT_RUNS,
            )
            training.auto_deploy_error = (
                "Deployment failed due to high volume of requests. "
                "Wait a few minutes or increase the 'MAX_PARALLEL_BOT_RUNS' "
                "environment variable."
            )
            return

    try:
        bot_session = run_bot_from_raw_configs(
            deployment_id,
            training.model_name,
            training.base_url,
            training.zip_bot_configs or {},
        )
        running_bots[deployment_id] = bot_session
        structlogger.info("model_api.auto_deploy.started", deployment_id=deployment_id)
    except Exception as e:
        structlogger.error(
            "model_api.auto_deploy.failed",
            deployment_id=deployment_id,
            error=str(e),
        )


async def _stream_bot_statuses(
    resp: ResponseStream, bot: BotSession, deployment_id: str
) -> None:
    """Stream bot deployment status events until the bot reaches a terminal state."""
    bot_terminal_statuses = {BotSessionStatus.RUNNING, BotSessionStatus.STOPPED}
    last_status: Optional[str] = None
    keepalive_counter = 0
    while True:
        current_status = bot.status
        is_terminal = current_status in bot_terminal_statuses
        if current_status != last_status:
            payload: Dict[str, Any] = {
                "deployment_id": deployment_id,
                "status": current_status,
                "url": bot.url,
                "returncode": bot.returncode,
            }
            deployment_error = _deployment_error_from_bot(bot)
            if deployment_error is not None:
                payload["error"] = deployment_error
            if is_terminal:
                payload["logs"] = get_logs_content(bot.log_id)
            await resp.write(f"data: {json_stdlib.dumps(payload)}\n\n")
            last_status = current_status
        if is_terminal:
            break
        await asyncio.sleep(0.5)
        keepalive_counter += 1
        if keepalive_counter % 30 == 0:
            await resp.write(": keepalive\n\n")


def _deployment_error_from_bot(bot: BotSession) -> Optional[str]:
    """Return a deployment error string when the bot session recorded one."""
    error = getattr(bot, "error", None)
    if isinstance(error, str):
        return error
    return None


def _bot_status_json_payload(bot: BotSession, deployment_id: str) -> Dict[str, Any]:
    """Build the JSON payload for a bot deployment status response."""
    payload: Dict[str, Any] = {
        "deployment_id": deployment_id,
        "status": bot.status,
        "returncode": bot.returncode,
        "url": bot.url,
        "logs": get_logs_content(bot.log_id),
    }
    deployment_error = _deployment_error_from_bot(bot)
    if deployment_error is not None:
        payload["error"] = deployment_error
    return payload


_BOT_DATA_FETCH_TIMEOUT = aiohttp.ClientTimeout(total=10, sock_connect=2, sock_read=8)

_BOT_SUBPROCESS_ORIGIN_TEMPLATE = "http://localhost:{port}"
_CONVERSATION_ID_SEGMENT_PATTERN = re.compile(r"[A-Za-z0-9._~:@+-]{1,255}")
_INVALID_CONVERSATION_ID_MESSAGE = "Invalid conversation id"


def _get_running_bot(deployment_id: str) -> Optional[BotSession]:
    """Return the running bot session for ``deployment_id``, if one exists."""
    bot = running_bots.get(deployment_id)
    if bot is None or bot.status != BotSessionStatus.RUNNING:
        return None
    return bot


def _bot_subprocess_url(bot: BotSession, path: str) -> str:
    """Return the loopback URL of ``path`` on the bot subprocess."""
    encoded_path = "/".join(quote(segment, safe="") for segment in path.split("/"))
    origin = _BOT_SUBPROCESS_ORIGIN_TEMPLATE.format(port=bot.port)
    return f"{origin}/{encoded_path}"


async def _fetch_bot_endpoint(
    bot: BotSession,
    path: str,
    failed_log_key: str,
    params: Optional[Dict[str, str]] = None,
) -> Tuple[int, Dict[str, Any] | str]:
    """Fetch an endpoint from the bot subprocess."""
    endpoint_url = _bot_subprocess_url(bot, path)
    try:
        async with aiohttp.ClientSession(timeout=_BOT_DATA_FETCH_TIMEOUT) as session:
            async with session.get(endpoint_url, params=params) as resp:
                if resp.content_type and "json" in resp.content_type:
                    body: Dict[str, Any] | str = await resp.json()
                else:
                    body = await resp.text()
                return resp.status, body
    except aiohttp.ClientError:
        structlogger.error(
            failed_log_key,
            deployment_id=bot.deployment_id,
        )
        return HTTPStatus.BAD_GATEWAY, {"message": "Bot unreachable"}


async def _fetch_bot_data(bot: BotSession) -> Tuple[int, Dict[str, Any] | str]:
    """Fetch bot flows/domain JSON from the bot subprocess internal /data endpoint."""
    return await _fetch_bot_endpoint(
        bot,
        "data",
        "model_api.bot_data.fetch_failed",
    )


def _allowlisted_tracker_query_params(request: Request) -> Optional[Dict[str, str]]:
    """Return allowlisted tracker query params to forward to the bot subprocess."""
    if "start_session" not in request.args:
        return None
    return {"start_session": request.args.get("start_session")}


def _tracker_path_for_conversation(conversation_id: str) -> Optional[str]:
    """Return the bot tracker path for a conversation id, or None if invalid."""
    segments = conversation_id.split("/")
    for segment in segments:
        if segment in {".", ".."}:
            return None
        if not _CONVERSATION_ID_SEGMENT_PATTERN.fullmatch(segment):
            return None

    return f"conversations/{conversation_id}/tracker"


async def _fetch_bot_tracker(
    bot: BotSession,
    tracker_path: str,
    params: Optional[Dict[str, str]] = None,
) -> Tuple[int, Dict[str, Any] | str]:
    """Fetch a conversation tracker from the bot subprocess."""
    return await _fetch_bot_endpoint(
        bot,
        tracker_path,
        "model_api.bot_tracker.fetch_failed",
        params=params,
    )


def _bot_proxy_response(
    status: int, body: Dict[str, Any] | str
) -> response.HTTPResponse:
    """Return a bot subprocess response to the proxy caller."""
    if status == HTTPStatus.BAD_GATEWAY:
        return json(body, status=HTTPStatus.BAD_GATEWAY)
    if isinstance(body, dict):
        return json(body, status=status)
    return response.text(body, status=status)


def update_status_of_all_trainings() -> None:
    """Update the status of all training processes."""
    running = list(trainings.values())
    for training in running:
        update_training_status(training)
        if (
            training.status == TrainingSessionStatus.DONE
            and training.deploy
            and not training.deploy_attempted
        ):
            _auto_deploy_bot(training)
            training.deploy_attempted = True


async def update_status_of_all_bots() -> None:
    """Update the status of all bot processes."""
    # we need to get the values first, because (since we are async and waiting
    # within the loop) some other job on the asyncio loop could change the dict
    # (adding or removing). python doesn't like if you change the size of a dict
    # while iterating over it and will raise a RuntimeError. so we get the values
    # first and iterate over them to avoid that.
    running = list(running_bots.values())
    for bot in running:
        await update_bot_status(bot)


def base_server_url(request: Request) -> str:
    """Return the base URL of the server."""
    if SERVER_BASE_URL:
        return SERVER_BASE_URL.rstrip("/")
    else:
        return f"{request.scheme}://{request.host}/{config.DEFAULT_SERVER_PATH_PREFIX}"


async def continuously_update_process_status() -> None:
    """Regularly Update the status of all training and bot processes."""
    structlogger.debug("model_api.update_process_status.started")

    while True:
        try:
            update_status_of_all_trainings()
            await update_status_of_all_bots()
        except asyncio.exceptions.CancelledError:
            structlogger.debug("model_api.update_process_status.cancelled")
            break
        except Exception as e:
            structlogger.error("model_api.update_process_status.error", error=str(e))
        finally:
            await asyncio.sleep(0.1)


def requires_studio_auth() -> Callable[[Callable], Callable[..., Any]]:
    """Gate a route behind the app's resolved auth policy.

    keycloak-legacy mode passes REST through unauthenticated by design
    (Studio 1.x parity — spec SWI-1437).

    Must be the OUTERMOST decorator (listed first under ``@bp.*``, executed
    first) on stacked routes, so unauthenticated requests never reach the
    capacity/disk gates and cannot observe 429/507 responses pre-auth.
    """

    def decorator(f: Callable) -> Callable:
        @wraps(f)
        async def decorated(request: Request, *args: Any, **kwargs: Any) -> Any:
            rejection = await _reject_unauthenticated_request(request)
            if rejection is not None:
                return rejection

            result = f(request, *args, **kwargs)
            return await result if isawaitable(result) else result

        decorated.__requires_studio_auth__ = True  # type: ignore[attr-defined]
        return decorated

    return decorator


async def _reject_unauthenticated_request(
    request: Request,
) -> Optional[response.HTTPResponse]:
    """Return an auth error response, or None when the request may proceed."""
    policy = auth.policy_from_app(request.app)
    if policy is None:
        return _auth_error_response(
            "AuthNotConfigured",
            "Authentication is not configured for the model service. "
            "Set STUDIO_AUTH_URL (or KEYCLOAK_URL for Studio 1.x).",
        )

    if policy.rest_verifier is None:
        # open REST: mark anonymous so the attribute exists in every mode
        request.ctx.authenticated_user = None
        return None

    token = _bearer_token(request.headers.get("authorization"))
    if token is None:
        return _unauthenticated_response()

    try:
        request.ctx.authenticated_user = await policy.rest_verifier.verify(token)
    except auth.AuthenticationError:
        return _unauthenticated_response()
    except auth.AuthUnavailableError:
        return _auth_error_response(
            "AuthUnavailable",
            "Could not verify the session token against Studio.",
        )

    return None


def _auth_error_response(code: str, message: str) -> response.HTTPResponse:
    """Return a 503 response for an auth backend that cannot be used."""
    exc = ErrorResponse(HTTPStatus.SERVICE_UNAVAILABLE, code, message)
    return response.json(exc.error_info, status=exc.status)


def _bearer_token(header: Optional[str]) -> Optional[str]:
    if not header:
        return None
    scheme, _, token = header.partition(" ")
    if scheme.lower() != "bearer" or not token.strip():
        return None
    return token.strip()


def _unauthenticated_response() -> response.HTTPResponse:
    # Deliberately does not say WHY the token failed.
    exc = ErrorResponse(
        HTTPStatus.UNAUTHORIZED, "NotAuthenticated", "User is not authenticated."
    )
    return response.json(
        exc.error_info, status=exc.status, headers={"WWW-Authenticate": "Bearer"}
    )


def external_blueprint() -> Blueprint:
    """Create a blueprint for the model manager API."""
    from rasa.core.channels.socketio import SocketBlueprint

    sio_server = AsyncServer(
        async_mode="sanic", cors_allowed_origins=config.CORS_ORIGINS
    )
    bp = SocketBlueprint(sio_server, "", "model_api")

    create_bridge_server(sio_server, running_bots)

    @bp.before_server_stop
    async def cleanup_processes(app: Sanic, loop: asyncio.AbstractEventLoop) -> None:
        """Terminate all running processes before the server stops."""
        structlogger.debug("model_api.cleanup_processes.started")
        cleanup_training_processes()
        cleanup_bot_processes()
        shutdown_warm_rasa_processes()

    @bp.after_server_start
    async def create_warm_rasa_processes(
        app: Sanic, loop: asyncio.AbstractEventLoop
    ) -> None:
        """Create warm Rasa processes to speed up future training and bot runs."""
        structlogger.debug("model_api.create_warm_rasa_processes.started")
        initialize_warm_rasa_process()

    @bp.after_server_start
    async def attach_auth_policy(app: Sanic, loop: asyncio.AbstractEventLoop) -> None:
        if auth.policy_from_app(app) is not None:
            return  # tests may pre-attach a stub policy
        policy = auth.resolve_auth_policy(config.STUDIO_AUTH_URL, config.KEYCLOAK_URL)
        if policy is None:
            structlogger.error(
                "model_api.auth.not_configured",
                event_info=(
                    "Neither STUDIO_AUTH_URL nor KEYCLOAK_URL is set. All "
                    "protected endpoints will return 503 and socket "
                    "connections will be refused until one is configured."
                ),
            )
            return
        app.ctx.auth_policy = policy

    @bp.before_server_stop
    async def close_auth_policy(app: Sanic, loop: asyncio.AbstractEventLoop) -> None:
        policy = auth.policy_from_app(app)
        if policy is None:
            return
        # Visits both slots rather than assuming they alias: the shared
        # studio-mode verifier tolerates a second close() (it's idempotent),
        # and a future mode with distinct verifiers can't silently leak one.
        for verifier in (policy.rest_verifier, policy.socket_verifier):
            if verifier is not None:
                await verifier.close()

    def limit_parallel_training_requests() -> Callable[[Callable], Callable[..., Any]]:
        """Limit the number of parallel training requests."""

        def decorator(f: Callable) -> Callable:
            @wraps(f)
            def decorated(*args: Any, **kwargs: Any) -> Any:
                running_requests = len(
                    [
                        training
                        for training in trainings.values()
                        if training.status == TrainingSessionStatus.RUNNING
                        and training.process.poll() is None
                    ]
                )

                if running_requests >= int(config.MAX_PARALLEL_TRAININGS):
                    return response.json(
                        {
                            "message": f"Too many parallel training requests, above "
                            f"the limit of {config.MAX_PARALLEL_TRAININGS}. "
                            f"Retry later or increase your server's "
                            f"memory and CPU resources."
                        },
                        status=HTTPStatus.TOO_MANY_REQUESTS,
                    )
                return f(*args, **kwargs)

            return decorated

        return decorator

    def limit_parallel_bot_runs() -> Callable[[Callable], Callable[..., Any]]:
        """Limit the number of parallel training requests."""

        def decorator(f: Callable) -> Callable:
            @wraps(f)
            def decorated(*args: Any, **kwargs: Any) -> Any:
                running_requests = len(
                    [
                        bot
                        for bot in running_bots.values()
                        if bot.status
                        in {BotSessionStatus.RUNNING, BotSessionStatus.QUEUED}
                    ]
                )

                if running_requests >= int(config.MAX_PARALLEL_BOT_RUNS):
                    return response.json(
                        {
                            "message": f"Too many parallel bot runs, above "
                            f"the limit of {config.MAX_PARALLEL_BOT_RUNS}. "
                            f"Retry later or increase your server's "
                            f"memory and CPU resources."
                        },
                        status=HTTPStatus.TOO_MANY_REQUESTS,
                    )

                return f(*args, **kwargs)

            return decorated

        return decorator

    def ensure_minimum_disk_space() -> Callable[[Callable], Callable[..., Any]]:
        """Ensure that there is enough disk space before starting a new process."""
        min_required_disk_space = 1024 * 1024 * config.MIN_REQUIRED_DISCSPACE_MB

        def decorator(f: Callable) -> Callable:
            @wraps(f)
            def decorated(*args: Any, **kwargs: Any) -> Any:
                if os.path.exists(config.SERVER_BASE_WORKING_DIRECTORY):
                    free_space_bytes = psutil.disk_usage(
                        config.SERVER_BASE_WORKING_DIRECTORY
                    ).free
                    structlogger.debug(
                        "model_api.storage.available_disk_space",
                        available_space_mb=free_space_bytes / 1024 / 1024,
                    )

                    if free_space_bytes < min_required_disk_space:
                        return response.json(
                            {
                                "message": (
                                    f"Less than {config.MIN_REQUIRED_DISCSPACE_MB} MB "
                                    f"of free disk space available. "
                                    f"Please free up some space on the model service."
                                )
                            },
                            status=HTTPStatus.INSUFFICIENT_STORAGE,
                        )

                return f(*args, **kwargs)

            return decorated

        return decorator

    @bp.get("/training")
    @requires_studio_auth()
    async def get_training_list(request: Request) -> response.HTTPResponse:
        """Return a list of all training sessions for an assistant."""
        assistant_id = request.args.get("assistant_id")
        sessions = [
            {
                "training_id": session.training_id,
                "assistant_id": session.assistant_id,
                "client_id": session.client_id,
                "progress": session.progress,
                "status": session.status,
                "model_name": session.model_name,
                "runtime_metadata": None,
            }
            for session in trainings.values()
            if session.assistant_id == assistant_id
        ]
        return json({"training_sessions": sessions, "total_number": len(sessions)})

    @bp.post("/training")
    @requires_studio_auth()
    @limit_parallel_training_requests()
    @ensure_minimum_disk_space()
    async def start_training(request: Request) -> response.HTTPResponse:
        """Start a new training session.

        Accepts either ``multipart/form-data`` with a ``zip`` file field and
        ``id`` / ``assistant_id`` / ``client_id`` form fields, or the JSON body
        with a ``bot_config.data`` payload as base64-encoded files.
        """
        if request.content_type and "multipart/form-data" in request.content_type:
            training_id = request.form.get("id")
            assistant_id = request.form.get("assistant_id")
            client_id = request.form.get("client_id")
            deploy = (request.form.get("deploy") or "").lower() == "true"
            zip_file = request.files.get("zip")
            if not zip_file:
                return json({"message": "zip file is required"}, status=400)
            zip_bytes: Optional[bytes] = zip_file.body
            encoded_training_data = None
            model_name: Optional[str] = training_id
        else:
            data = request.json
            training_id = data.get("id")
            assistant_id = data.get("assistant_id")
            client_id = data.get("client_id")
            deploy_raw = data.get("deploy", False)
            deploy = (
                str(deploy_raw).lower() == "true"
                if isinstance(deploy_raw, str)
                else bool(deploy_raw)
            )
            encoded_training_data = data.get("bot_config", {}).get("data", {})
            zip_bytes = None
            model_name = None

        if deploy and zip_bytes is None:
            return json({"message": "deploy=true requires a zip file"}, status=400)

        if training_id in trainings:
            if not deploy:
                return json(
                    {"message": "Training with this id already exists"}, status=409
                )
            existing = trainings[training_id]
            if not existing.deploy:
                return json({"message": "Existing was not deploy=true"}, status=400)
            if zip_bytes is None:
                return json(
                    {"message": "Existing deploy=true requires a zip file"}, status=400
                )
            existing.deploy_attempted = False
            existing.auto_deploy_error = None
            return json({"training_id": training_id, "model_name": existing.model_name})

        if not assistant_id:
            return json({"message": "Assistant id is required"}, status=400)

        if not training_id:
            return json({"message": "Training id is required"}, status=400)

        try:
            # file deepcode ignore PT: path traversal is prevented
            # by the `subpath` function found in the `rasa.model_manager.utils` module
            training_session = run_training(
                training_id=training_id,
                assistant_id=assistant_id,
                client_id=client_id,
                encoded_training_data=encoded_training_data,
                zip_bytes=zip_bytes,
                model_name=model_name,
                deploy=deploy,
                base_url=base_server_url(request),
            )
            trainings[training_id] = training_session
            return json(
                {"training_id": training_id, "model_name": training_session.model_name}
            )
        except InvalidPathException as exc:
            return json({"message": str(exc)}, status=403)
        except ValueError as exc:
            return json({"message": str(exc)}, status=400)
        except Exception as exc:
            return json({"message": str(exc)}, status=500)

    @bp.get("/training/<training_id>")
    @requires_studio_auth()
    async def get_training(
        request: Request, training_id: str
    ) -> ResponseStream | response.HTTPResponse:
        """Return the status of a training session.

        If ``stream_response=true`` is passed as a query parameter the response
        is an SSE stream that emits an event on every status/progress change and
        closes when the training reaches a terminal state.
        """
        training = trainings.get(training_id)
        if training is None:
            return json({"message": "Training not found"}, status=404)

        if request.args.get("stream_response", "").lower() != "true":
            return json(
                {
                    "training_id": training_id,
                    "assistant_id": training.assistant_id,
                    "client_id": training.client_id,
                    "progress": training.progress,
                    "model_name": training.model_name,
                    "status": training.status,
                    "logs": get_logs_content(training.log_id),
                }
            )

        terminal_statuses = {
            TrainingSessionStatus.DONE,
            TrainingSessionStatus.ERROR,
            TrainingSessionStatus.STOPPED,
        }

        async def stream_training(resp: ResponseStream) -> None:
            last_status: Optional[str] = None
            last_progress: Optional[int] = None
            keepalive_counter = 0

            while True:
                current_status = training.status
                current_progress = training.progress
                is_terminal = current_status in terminal_statuses

                if current_status != last_status or current_progress != last_progress:
                    payload: Dict[str, Any] = {
                        "training_id": training_id,
                        "status": current_status,
                        "progress": current_progress,
                    }
                    if is_terminal:
                        payload["logs"] = get_logs_content(training.log_id)
                    await resp.write(f"data: {json_stdlib.dumps(payload)}\n\n")
                    last_status = current_status
                    last_progress = current_progress

                if is_terminal:
                    break

                await asyncio.sleep(0.5)

                keepalive_counter += 1
                if keepalive_counter % 30 == 0:  # every ~15 s
                    await resp.write(": keepalive\n\n")

            if training.deploy and training.status == TrainingSessionStatus.DONE:
                # wait for _auto_deploy_bot to register a live bot session;
                # a STOPPED entry means an evicted bot not yet replaced
                for _ in range(20):
                    existing = running_bots.get(training_id)
                    if (
                        existing is not None
                        and existing.status != BotSessionStatus.STOPPED
                    ):
                        break
                    await asyncio.sleep(0.1)

                bot = running_bots.get(training_id)
                if bot is not None and bot.status != BotSessionStatus.STOPPED:
                    await _stream_bot_statuses(resp, bot, training_id)
                elif training.auto_deploy_error:
                    not_deployed_payload = json_stdlib.dumps(
                        {
                            "deployment_id": training_id,
                            "status": "not_deployed",
                            "logs": training.auto_deploy_error,
                        }
                    )
                    await resp.write(f"data: {not_deployed_payload}\n\n")

        return ResponseStream(stream_training, content_type="text/event-stream")

    @bp.delete("/training/<training_id>")
    @requires_studio_auth()
    async def stop_training(
        request: Request, training_id: str
    ) -> response.HTTPResponse:
        # this is a no-op if the training is already done
        if not (training := trainings.get(training_id)):
            return json({"message": "Training session not found"}, status=404)

        terminate_training(training)
        return json({"training_id": training_id})

    @bp.post("/bot")
    @requires_studio_auth()
    @limit_parallel_bot_runs()
    @ensure_minimum_disk_space()
    async def start_bot(request: Request) -> response.HTTPResponse:
        data = request.json
        deployment_id: Optional[str] = data.get("deployment_id")
        model_name: Optional[str] = data.get("model_name")
        encoded_configs: Dict[str, str] = data.get("bot_config", {})

        if deployment_id in running_bots:
            # fail, because there apparently is already a bot running with this id
            return json(
                {"message": "Bot with this deployment id already exists"}, status=409
            )

        if not deployment_id:
            return json({"message": "Deployment id is required"}, status=400)

        if not model_name:
            return json({"message": "Model name is required"}, status=400)

        base_url_path = base_server_url(request)
        try:
            bot_session = run_bot(
                deployment_id,
                model_name,
                base_url_path,
                encoded_configs,
            )
            running_bots[deployment_id] = bot_session
            return json(
                {
                    "deployment_id": deployment_id,
                    "status": bot_session.status,
                    "url": bot_session.url,
                }
            )
        except ModelNotFound:
            return json(
                {"message": f"Model with name '{model_name}' could not be found."},
                status=404,
            )
        except Exception as e:
            return json({"message": str(e)}, status=500)

    @bp.delete("/bot/<deployment_id>")
    @requires_studio_auth()
    async def stop_bot(request: Request, deployment_id: str) -> response.HTTPResponse:
        bot = running_bots.get(deployment_id)
        if bot is None:
            return json({"message": _BOT_NOT_FOUND_MESSAGE}, status=404)

        terminate_bot(bot)
        return json(
            {"deployment_id": deployment_id, "status": bot.status, "url": bot.url}
        )

    @bp.get("/bot/<deployment_id>")
    @requires_studio_auth()
    async def get_bot(
        request: Request, deployment_id: str
    ) -> ResponseStream | response.HTTPResponse:
        """Return the status of a bot deployment.

        If ``stream_response=true`` is passed as a query parameter the response
        is an SSE stream that emits an event on every status change and closes
        when the bot reaches ``stopped``.
        """
        bot = running_bots.get(deployment_id)
        if bot is None:
            return json({"message": _BOT_NOT_FOUND_MESSAGE}, status=404)

        if request.args.get("stream_response", "").lower() != "true":
            return json(_bot_status_json_payload(bot, deployment_id))

        async def stream_bot(resp: ResponseStream) -> None:
            await _stream_bot_statuses(resp, bot, deployment_id)

        return ResponseStream(stream_bot, content_type="text/event-stream")

    @bp.get("/bot/<deployment_id>/data")
    @requires_studio_auth()
    async def get_bot_data(
        request: Request, deployment_id: str
    ) -> response.HTTPResponse:
        """Proxy the bot's /data endpoint for browser-facing Inspector flows."""
        bot = _get_running_bot(deployment_id)
        if bot is None:
            return json({"message": _BOT_NOT_FOUND_MESSAGE}, status=404)

        status, body = await _fetch_bot_data(bot)
        return _bot_proxy_response(status, body)

    @bp.get("/bot/<deployment_id>/conversations/<conversation_id:path>/tracker")
    @requires_studio_auth()
    async def get_bot_tracker(
        request: Request, deployment_id: str, conversation_id: str
    ) -> response.HTTPResponse:
        """Proxy a conversation tracker from the bot's Rasa server API."""
        bot = _get_running_bot(deployment_id)
        if bot is None:
            return json({"message": _BOT_NOT_FOUND_MESSAGE}, status=404)

        tracker_path = _tracker_path_for_conversation(conversation_id)
        if tracker_path is None:
            return json({"message": _INVALID_CONVERSATION_ID_MESSAGE}, status=400)

        status, body = await _fetch_bot_tracker(
            bot, tracker_path, params=_allowlisted_tracker_query_params(request)
        )
        return _bot_proxy_response(status, body)

    @bp.get("/bot")
    @requires_studio_auth()
    async def list_bots(request: Request) -> response.HTTPResponse:
        bots = [
            {
                "deployment_id": bot.deployment_id,
                "status": bot.status,
                "returncode": bot.returncode,
                "url": bot.url,
            }
            for bot in running_bots.values()
        ]
        return json({"deployment_sessions": bots, "total_number": len(bots)})

    @bp.route("/models/<model_name>", methods=["GET"])
    @requires_studio_auth()
    async def send_model(
        request: Request, model_name: str
    ) -> response.ResponseStream | response.HTTPResponse:
        try:
            model_path = path_to_model(model_name)

            # get size of model file
            model_size = os.stat(model_path)

            return await response.file_stream(
                model_path, headers={"Content-Length": str(model_size.st_size)}
            )
        except NotFound:
            return json({"message": "Model not found"}, status=404)
        except ModelNotFound:
            return json({"message": "Model not found"}, status=404)

    @bp.route("/models/<model_name>", methods=["HEAD"])
    @requires_studio_auth()
    async def head_model(request: Request, model_name: str) -> response.HTTPResponse:
        try:
            model_size = size_of_model(model_name)

            structlogger.debug(
                "model_api.internal.head_model",
                model_name=model_name,
                size=model_size,
            )
            return response.raw(
                b"", status=200, headers={"Content-Length": str(model_size)}
            )
        except ModelNotFound:
            return response.raw(b"", status=404)

    @bp.post("/defaults")
    @requires_studio_auth()
    async def get_defaults(request: Request) -> response.HTTPResponse:
        """Returns the system defaults like prompts, patterns, etc."""
        body = request.json or {}
        config_yaml = body.get("config")
        if config_yaml is None:
            exc = ErrorResponse(
                HTTPStatus.BAD_REQUEST,
                "BadRequest",
                "Missing `config` key in request body.",
            )
            return response.json(exc.error_info, status=exc.status)

        endpoints_yaml = body.get("endpoints")
        if endpoints_yaml is None:
            exc = ErrorResponse(
                HTTPStatus.BAD_REQUEST,
                "BadRequest",
                "Missing `endpoints` key in request body.",
            )
            return response.json(exc.error_info, status=exc.status)

        try:
            defaults = get_rasa_defaults(config_yaml, endpoints_yaml)
        except (YAMLError, InvalidConfigException) as e:
            exc = ErrorResponse(
                HTTPStatus.INTERNAL_SERVER_ERROR,
                "InitDataError",
                f"Failed to load defaults. Error: {e!s}",
            )
            return response.json(exc.error_info, status=exc.status)
        return response.json(defaults.model_dump(exclude_none=True))

    @bp.get("/project_template")
    @requires_studio_auth()
    async def get_project_template(request: Request) -> response.HTTPResponse:
        """Return initial project template data."""
        template = request.args.get("template", ProjectTemplateName.DEFAULT.value)

        try:
            template_enum = ProjectTemplateName(template)
        except ValueError:
            valid_templates = ", ".join([t.value for t in ProjectTemplateName])
            exc = ErrorResponse(
                HTTPStatus.BAD_REQUEST,
                "BadRequest",
                f"Unknown template '{template}'. Valid templates: {valid_templates}",
            )
            return response.json(exc.error_info, status=exc.status)

        template_dir = scaffold_path(template_enum)
        if not os.path.isdir(template_dir):
            exc = ErrorResponse(
                HTTPStatus.INTERNAL_SERVER_ERROR,
                "InitDataError",
                f"Template directory '{template_dir}' not found.",
            )
            return response.json(exc.error_info, status=exc.status)

        assistant_name, parts = build_calm_import_parts(
            data_path=f"{template_dir}/data",
            domain_path=f"{template_dir}/domain",
            config_path=f"{template_dir}/config.yml",
            endpoints_path=f"{template_dir}/endpoints.yml",
            assistant_name=template_enum.value,
        )

        defaults = get_rasa_defaults(
            config_yaml=dump_obj_as_yaml_to_string(parts.config),
            endpoints_yaml=dump_obj_as_yaml_to_string(parts.endpoints),
        )
        return response.json(
            {
                **parts.model_dump(exclude_none=True),
                "assistantName": assistant_name,
                "defaults": defaults.model_dump(exclude_none=True),
                "version": rasa.__version__,
            }
        )

    @bp.get("/health")
    async def health(request: Request) -> response.HTTPResponse:
        # Unauthenticated by design (deployment healthchecks). Keep the body
        # free of bot/training identifiers and internal URLs — the full
        # listings live behind the authenticated GET /bot and GET /training.
        return json({"status": "ok"})

    return bp


def size_of_model(model_name: str) -> Optional[int]:
    """Return the size of a model."""
    model_file_name = f"{model_name}.{MODEL_ARCHIVE_EXTENSION}"
    model_path = subpath(models_base_path(), model_file_name)

    if os.path.exists(model_path):
        return os.path.getsize(model_path)

    if config.SERVER_MODEL_REMOTE_STORAGE:
        structlogger.debug(
            "model_api.storage.fetching_remote_model_size",
            model_name=model_file_name,
        )
        return fetch_size_of_remote_model(
            model_file_name, config.SERVER_MODEL_REMOTE_STORAGE, model_path
        )
    raise ModelNotFound("Model not found.")


def path_to_model(model_name: str) -> Optional[str]:
    """Return the path to a local model."""
    model_file_name = f"{model_name}.{MODEL_ARCHIVE_EXTENSION}"
    model_path = subpath(models_base_path(), model_file_name)

    if os.path.exists(model_path):
        return model_path

    if config.SERVER_MODEL_REMOTE_STORAGE:
        structlogger.info(
            "model_api.storage.fetching_remote_model",
            model_name=model_file_name,
        )
        return fetch_remote_model_to_dir(
            model_file_name,
            models_base_path(),
            config.SERVER_MODEL_REMOTE_STORAGE,
        )

    raise ModelNotFound("Model not found.")
